float sdSphere(vec3 point, float scale) {
    return length(point) - scale;
}

float sdBox(vec3 point, vec3 b) {
    vec3 q = abs(point) - b;
    return length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0);
}

float smin(float a, float b, float k) {
    float h = max(k - abs(a - b), 0.0) / k;
    return min(a, b) - h*h*h*k*(1.0 / 6.0);
}


mat2 rot(float angle) {
    float s = sin(angle);
    float c = cos(angle);
    return mat2(c, -s, s, c);
}

float map(vec3 point) {
    vec3 position = vec3(0.0, 0.0, 0.0);

    vec3 q = point;
    q.z += iTime * 1.5;
    q = mod(q, 1.0) - 0.5;


    float sphere = sdSphere(point - position, 2.0);
    float box = sdSphere(q, 0.15);

    return min(box, sphere);
}

vec3 palette(float t) {
    return .5+.5*cos(3.14159265 * (t+vec3(1.5, 1.0, 0.0)));
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 uv = (fragCoord * 2. - iResolution.xy) / iResolution.y;
    vec2 m = (iMouse.xy * 2. - iResolution.xy) / iResolution.y;

    vec3 origin = vec3(0, 0, -4);
    vec3 direction = normalize(vec3(uv.xy * 1.25, 1));
    vec3 color = vec3(0);

    float dist = 1.0;

    origin.yz *= rot(-m.y);
    direction.yz *= rot(-m.y);

    origin.xz *= rot(-m.x);
    direction.xz *= rot(-m.x);

    int steps = 80;
    for (int i = 0; i < steps; i++) {
        vec3 point = origin + direction * dist;

        float currentDistance = map(point);
        dist += currentDistance;

        if (currentDistance < .001) break;
        if (dist > 100.) break;
    }

    color = palette(dist * 0.4);
    fragColor = vec4(color, 1.0);
}
